const subjects=[
{id:'matematik',name:'Matematik',short:'Ma',code:'MATE',desc:'Se sambanden mellan formler, grafer och förändring.',area:'Algebra & funktioner'},
{id:'fysik',name:'Fysik',short:'Fy',code:'FYSK',desc:'Gör krafter, rörelse och energi begripliga.',area:'Krafter & rörelse'},
{id:'kemi',name:'Kemi',short:'Ke',code:'KEMI',desc:'Koppla det som händer till atomer och reaktionsformler.',area:'Reaktioner & substansmängd'},
{id:'svenska',name:'Svenska',short:'Sv',code:'SVEN',desc:'Upptäck hur språk och texter är uppbyggda.',area:'Text & argumentation'},
{id:'engelska',name:'Engelska',short:'En',code:'ENGE',desc:'Undersök hur grammatik och textbindning skapar mening.',area:'Grammar & communication'}];
const lessons=[
{id:'formler-som-balans',s:'matematik',title:'Formler som balans',level:'1a / 1b / 1c',code:'MATE1A00X · MATE1B00X · MATE1C00X',time:8,art:'A = b · h',desc:'Följ en formelomvandling steg för steg. Se vad som händer när båda leden divideras med samma tal.',goal:'Förstå varför samma operation måste göras i båda leden.',ci:'Hantering av formler och algebraiska uttryck.',kind:'formula'},
{id:'funktioner-och-grafer',s:'matematik',title:'En funktion – flera uttryck',level:'1b / 1c',code:'MATE1B00X · MATE1C00X',time:10,art:'y = kx + m',desc:'Ändra lutning och startvärde. Se hur grafen, formeln och värdena förändras tillsammans.',goal:'Koppla en linjär funktions formel till dess graf och värdetabell.',ci:'Funktionsrepresentationer, linjära funktioner och räta linjens ekvation.',kind:'graph'},
{id:'kraft-och-rorelse',s:'fysik',title:'Kraft är inte hastighet',level:'1a1 / 1b',code:'FYSK1A10X · FYSK1B00X',time:10,art:'← F →',desc:'Ändra två motriktade krafter på en vagn. Jämför kraftresultanten med hur hastigheten förändras.',goal:'Skilja mellan hastighet och acceleration.',ci:'Krafter som orsak till förändring av hastighet och rätlinjig rörelse.',kind:'force'},
{id:'rorelse-och-grafer',s:'fysik',title:'Läs rörelsens graf',level:'1a1 / 1b',code:'FYSK1A10X · FYSK1B00X',time:10,art:'s(t) ↗',desc:'Flytta tidpunkten längs en läge–tid-graf och följ föremålets position. Jämför vila med rörelse åt olika håll.',goal:'Förstå att grafens lutning visar hastigheten, inte positionen.',ci:'Likformig rätlinjig rörelse och analys av grafer.',kind:'motion'},
{id:'balansera-reaktioner',s:'kemi',title:'Atomerna ska räcka till',level:'1',code:'KEMI1000X',time:10,art:'H₂ + O₂ → H₂O',desc:'Ändra antalet molekyler och följ atomräkningen på båda sidor av reaktionspilen.',goal:'Förstå skillnaden mellan koefficienter och index i en reaktionsformel.',ci:'Materiens oförstörbarhet och formler för kemiska reaktioner.',kind:'balance'},
{id:'begransande-reaktant',s:'kemi',title:'Vilket ämne tar slut först?',level:'1',code:'KEMI1000X',time:10,art:'2 H₂ + O₂ → 2 H₂O',desc:'Välj hur många väte- och syremolekyler som finns. Se hur mycket vatten som kan bildas och vad som blir över.',goal:'Koppla reaktionsformelns proportioner till begränsande reaktant.',ci:'Substansmängdförhållanden, begränsande reaktanter och utbyte.',kind:'limiting'},
{id:'bygg-ett-argument',s:'svenska',title:'Så hänger ett argument ihop',level:'1',code:'SVEN1000X',time:8,art:'Tes ← skäl ← belägg',desc:'Utforska en kort argumenterande text. Markera textdelar och se vilken roll de spelar i resonemanget.',goal:'Skilja en tes från argument, belägg och bemötande.',ci:'Argumenterande skrivande samt struktur och språkliga drag i texter.',kind:'argument'},
{id:'kallans-rost',s:'svenska',title:'Vems röst hörs i texten?',level:'1',code:'SVEN1000X',time:8,art:'Källa → referat → tanke',desc:'Jämför citat, referat och egen kommentar. Synliggör gränsen mellan källans ord och skribentens slutsats.',goal:'Göra det tydligt vad som kommer från en källa och vad som är en egen tanke.',ci:'Citat- och referatteknik samt kritisk läsning.',kind:'source'},
{id:'time-and-tense',s:'engelska',title:'Time and tense',level:'1',code:'ENGE1000X',time:8,art:'THEN ───── NOW',desc:'Jämför simple past och present perfect på en tidslinje. Se hur tidsuttryck och sammanhang påverkar valet.',goal:'Välja tempus utifrån om en tidsperiod är avslutad eller har koppling till nuet.',ci:'Grammatiska strukturer i egen kommunikation och uttryck för tidsaspekt.',kind:'tense'},
{id:'text-connect',s:'engelska',title:'Make the text connect',level:'1',code:'ENGE1000X',time:8,art:'because · however · so',desc:'Byt sambandsord mellan två idéer. Se hur orsaker, motsättningar och följder gör resonemanget tydligare.',goal:'Förstå hur sambandsord påverkar relationen mellan meningar.',ci:'Textbindning och uttryck som skapar struktur och sammanhang.',kind:'connect'}];
const main=document.getElementById('main');
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'reset_visualization',description:'Reset the currently open visualization to its initial state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object');const button=document.getElementById('reset');if(!button)throw new Error('Open a visualization first');button.click();return {reset:true}}},{signal:lifecycle.signal})).catch(()=>{});addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
const path=location.pathname.split('/').filter(Boolean),sub=subjects.find(s=>s.id===path[0]),lesson=lessons.find(l=>l.id===path[1]&&l.s===path[0]);
document.getElementById('sidebar').innerHTML=`<a class="brand" href="/">Gymnasie<br>visualiseringar<small>UNDERSÖK · FÖRSTÅ</small></a><nav aria-label="Ämnen"><a href="/" class="${!path.length?'active':''}" ${!path.length?'aria-current="page"':''}><span class="nav-icon">⌂</span>Alla ämnen</a>${subjects.map(s=>`<a href="/${s.id}/" class="${sub===s?'active':''}" ${sub===s?'aria-current="page"':''}><span class="nav-icon">${s.short}</span>${s.name}</a>`).join('')}</nav><div class="sidebar-end">Ett begrepp i taget.<br>För gymnasiet, enligt Gy25.<a href="/om/">Om materialet</a><a href="https://paulbelfrage.se/">Paul Belfrages kurssidor ↗</a></div>`;
function card(l){return `<a class="card" href="/${l.s}/${l.id}/"><div class="card-art" aria-hidden="true">${l.art}</div><div class="card-body"><span class="badge">Nivå ${l.level} · ${l.time} min</span><h3>${l.title}</h3><p>${l.desc}</p><p class="purpose"><strong>Syfte:</strong> ${l.goal}</p><div class="curriculum"><strong>Centralt innehåll · Gy25</strong>${l.ci}</div><div class="open">Öppna visualiseringen <span aria-hidden="true">↗</span></div></div></a>`}
if(!path.length){main.innerHTML=`<section class="intro"><p class="eyebrow">Interaktiva begrepp · Gymnasiet</p><h1>Svåra begrepp.<br>Synliga samband.</h1><p class="lead">Välj ett ämne och undersök ett begrepp. Varje visualisering hjälper dig att se vad som händer – och förklara varför.</p></section><div class="section-head"><h2>Vad vill du förstå?</h2><span>5 ämnen · 10 visualiseringar</span></div><div class="grid subjects">${subjects.map(s=>`<a class="card subject-card" href="/${s.id}/"><span class="subject-icon" aria-hidden="true">${s.short}</span><h3>${s.name}</h3><p>${s.desc}</p><div class="open">2 visualiseringar <span aria-hidden="true">↗</span></div></a>`).join('')}</div><div class="note"><strong>Gissa först. Undersök sedan.</strong><p>Gör en förutsägelse innan du ändrar något. Jämför resultatet med din tanke och försök förklara skillnaden.</p></div>`}
else if(lesson){renderLesson(lesson)}
else if(sub){document.title=sub.name+' – Gymnasievisualiseringar';main.innerHTML=`<div class="crumb"><a href="/">Alla ämnen</a> / ${sub.name}</div><section class="intro"><p class="eyebrow">${sub.area}</p><h1>${sub.name}</h1><p class="lead">${sub.desc} Välj en ruta för att öppna visualiseringen.</p></section><div class="section-head"><h2>Börja med de här begreppen</h2><span>2 visualiseringar · Gy25</span></div><div class="grid">${lessons.filter(l=>l.s===sub.id).map(card).join('')}</div><p class="legend">Ordningen är en pedagogisk rekommendation. Innehållskopplingarna är sammanfattningar av Skolverkets ämnesplan.</p>`}
else if(path[0]==='om'){main.innerHTML=`<div class="reading"><p class="eyebrow">Om materialet</p><h1>Förstå ett samband<br>i taget.</h1><p class="lead">Ett växande bibliotek för undervisning, repetition och egna upptäckter på gymnasiet.</p><h2>Så använder du en visualisering</h2><p>Läs den inledande frågan, gör en förutsägelse och undersök modellen. Försök sedan förklara resultatet med egna ord. Visualiseringarna kompletterar lärarens undervisning och praktiska övningar.</p><h2>Kopplingen till Gy25</h2><p>Varje övning visar ämne, nivå, nivåkod och relevant centralt innehåll. Beskrivningarna är korta parafraser. Valet av exempel och prioriteringen är pedagogiska bedömningar; Skolverket rangordnar inte vilka moment elever upplever som svårast.</p><p>Detta första utkast omfattar två visualiseringar per ämne. Modellerna förenklar verkligheten och deras antaganden anges i övningarna.</p><h2>Ämnesplaner hos Skolverket</h2><ul>${subjects.map(s=>`<li><a href="https://syllabuswebb.skolverket.se/subject/${s.code}/1/pdf">${s.name} · Gy25 (PDF)</a></li>`).join('')}</ul><p>Underlag granskat 10 september 2026. AI-assisterat material av Paul Belfrage.</p></div>`}
else{main.innerHTML='<h1>Sidan finns inte</h1><p><a href="/">Till alla ämnen</a></p>'}
function renderLesson(l){document.title=l.title+' – '+sub.name;main.innerHTML=`<div class="crumb"><a href="/">Alla ämnen</a> / <a href="/${sub.id}/">${sub.name}</a> / ${l.title}</div><p class="eyebrow">${sub.name} · Nivå ${l.level} · ${l.time} min</p><h1>${l.title}</h1><p class="lead">${l.goal}</p><section class="lab"><div class="lab-title"><h2>Undersök sambandet</h2><button id="reset">Börja om</button></div><div class="workspace" id="workspace"></div></section><section class="source"><h2>Koppling till Gy25</h2><p><strong>${sub.name}, nivå ${l.level}</strong><br>${l.code}</p><p>Centralt innehåll, sammanfattat: ${l.ci}</p><a href="https://syllabuswebb.skolverket.se/subject/${sub.code}/1/pdf">Läs Skolverkets ämnesplan (PDF) ↗</a></section>`;document.getElementById('reset').onclick=()=>setup(l.kind);setup(l.kind)}
function range(id,label,min,max,value,step=1){return `<label for="${id}">${label} <output id="${id}-out">${value}</output><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`}
function bind(fn){document.querySelectorAll('.workspace input,.workspace select').forEach(el=>el.addEventListener('input',()=>{const o=document.getElementById(el.id+'-out');if(o)o.textContent=el.value;fn()}));fn()}
function n(id){return Number(document.getElementById(id).value)}
function feedback(text,wrong=false){const e=document.getElementById('feedback');e.textContent=text;e.classList.toggle('wrong',wrong)}
function graph(k,m,t=null){const pts=Array.from({length:11},(_,x)=>`${55+x*48},${215-(k*x+m)*12}`).join(' ');return `<svg class="plot" viewBox="0 0 600 300" role="img" aria-label="Graf med lutning ${k} och startvärde ${m}"><defs><clipPath id="clip"><rect x="55" y="15" width="480" height="260"/></clipPath></defs>${[0,2,4,6,8,10].map(x=>`<path d="M${55+x*48} 20V275" stroke="#d9e4dd"/><text x="${55+x*48}" y="295" text-anchor="middle" font-size="13">${x}</text>`).join('')}${[-4,0,4,8,12,16].map(y=>`<path d="M55 ${215-y*12}H540" stroke="#d9e4dd"/><text x="42" y="${220-y*12}" text-anchor="end" font-size="13">${y}</text>`).join('')}<path d="M55 20V275M55 215H550" stroke="#68877a"/><polyline points="${pts}" stroke="#0f766e" stroke-width="3" fill="none" clip-path="url(#clip)"/>${t!==null?`<circle cx="${55+t*48}" cy="${215-(k*t+m)*12}" r="7" fill="#b45c1c" clip-path="url(#clip)"/>`:''}</svg>`}
function setup(kind){const w=document.getElementById('workspace');
if(kind==='formula'){w.innerHTML=`<p class="question">Hur kan du få h ensamt i formeln A = b · h?</p><p>Anta att b ≠ 0. Följ vad division med b gör med båda leden.</p><div class="visual"><div class="equation" id="formula">A = b · h</div></div><div class="controls"><button class="primary" id="step">Dividera båda leden med b</button></div><div id="feedback" class="feedback" aria-live="polite"></div><p>Pröva själv: lös ut t ur s = v · t. Vilket villkor behöver gälla?</p>`;let step=0;document.getElementById('step').onclick=()=>{step++;document.getElementById('formula').innerHTML=step===1?'A / b = (b · h) / b':'A / b = h';feedback(step===1?'Båda leden divideras med samma värde. Likheten bevaras eftersom b inte är noll.':'Faktorn b och divisionen med b tar ut varandra i högerledet. Kvar blir h.');document.getElementById('step').textContent=step===1?'Förenkla högerledet':'Klart';if(step>1)document.getElementById('step').disabled=true}}
if(kind==='graph'||kind==='motion'){const motion=kind==='motion';w.innerHTML=`<p class="question">${motion?'Kan positionen vara positiv medan hastigheten är negativ?':'Vad händer med grafen när startvärdet ändras men lutningen är densamma?'}</p><div class="controls">${range('k',motion?'Hastighet v (m/s)':'Lutning k',-1,1,.5,.25)}${range('m',motion?'Startposition (m)':'Startvärde m',0,5,2)}${motion?range('t','Tid (s)',0,10,0,.5):''}</div><div class="visual"><div class="equation" id="eq"></div><div id="plot"></div><div id="values" class="blocks"></div></div><div id="feedback" class="feedback" aria-live="polite"></div><p class="legend">${motion?'Modell: konstant hastighet längs en rät linje. Horisontell axel: tid i sekunder. Vertikal axel: position i meter.':'Horisontell axel: x. Vertikal axel: y. Varje steg åt höger ändrar y med k.'}</p>`;bind(()=>{let k=n('k'),m=n('m'),t=motion?n('t'):null;document.getElementById('eq').textContent=motion?`s = ${m} + (${k}) · t`:`y = ${k}x + ${m}`;document.getElementById('plot').innerHTML=graph(k,m,t);document.getElementById('values').innerHTML=motion?`<span class="text-block">t = ${t} s</span><span class="text-block">s = ${(m+k*t).toFixed(2)} m</span>`:[0,2,4].map(x=>`<span class="text-block">x = ${x} → y = ${m+k*x}</span>`).join('');feedback(motion?(k===0?'Positionen är oförändrad: föremålet står stilla.':`Positionen ${k>0?'ökar':'minskar'} med ${Math.abs(k)} meter varje sekund. Hastigheten avgörs av lutningen.`):'Startvärdet bestämmer skärningen med y-axeln. Lutningen bestämmer hur snabbt y ändras.');})}
if(kind==='force'){w.innerHTML=`<p class="question">En vagn rör sig redan åt höger. Stannar den om krafterna är lika stora?</p><div class="controls">${range('left','Kraft åt vänster (N)',0,20,10)}${range('right','Kraft åt höger (N)',0,20,10)}${range('time','Tid (s)',0,5,0,.5)}</div><div class="visual"><svg class="plot" viewBox="0 0 600 130" role="img" aria-label="Kraftdiagram för vagnen"><path d="M30 110H570" stroke="#a4bcae"/><rect x="265" y="42" width="70" height="45" rx="4" fill="#c3decf" stroke="#407959"/><circle cx="280" cy="97" r="9" fill="#407959"/><circle cx="320" cy="97" r="9" fill="#407959"/><g id="arrows"></g></svg><div id="force-values" class="blocks"></div></div><div id="feedback" class="feedback" aria-live="polite"></div><p class="legend">Modell: massa 2 kg, starthastighet +2 m/s och konstanta horisontella krafter. Positiv riktning är åt höger. Tyngdkraft och normalkraft balanserar varandra; övriga krafter försummas.</p>`;bind(()=>{let L=n('left'),R=n('right'),a=(R-L)/2,v=2+a*n('time');document.getElementById('arrows').innerHTML=`<path d="M265 64H${265-L*9}l8 -6m-8 6l8 6" fill="none" stroke="#ac631f" stroke-width="3" opacity="${L?1:0}"/><path d="M335 64H${335+R*9}l-8 -6m8 6l-8 6" fill="none" stroke="#0f766e" stroke-width="3" opacity="${R?1:0}"/>`;document.getElementById('force-values').innerHTML=[`Resultant: ${R-L} N`,`Acceleration: ${a} m/s²`,`Hastighet: ${v} m/s`].map(x=>`<span class="text-block">${x}</span>`).join('');feedback(a===0?'Krafterna balanserar varandra. Accelerationen är noll, men vagnen fortsätter med 2 m/s åt höger.':`Hastigheten ändras med ${a} m/s varje sekund. Flytta tiden för att följa förändringen.`)})}
if(kind==='balance'){w.innerHTML=`<p class="question">Hur många molekyler behövs för att antalet H- och O-atomer ska vara lika på båda sidor?</p><p>Ändra koefficienterna framför formlerna. Molekylernas index ligger fast.</p><div class="visual"><div class="reaction equation">${['H₂','O₂','H₂O'].map((x,i)=>`${i===1?'<span>+</span>':i===2?'<span>→</span>':''}<label><input id="c${i}" aria-label="Koefficient för ${x}" type="number" min="1" max="8" step="1" value="1">${x}</label>`).join('')}</div><div id="atoms"></div></div><button class="primary" id="check">Kontrollera minsta heltal</button><div class="feedback" id="feedback" aria-live="polite"></div>`;bind(()=>{let a=n('c0'),b=n('c1'),c=n('c2');document.getElementById('atoms').innerHTML=`<div class="bar-row"><span>H: ${2*a} / ${2*c}</span><div class="bar" style="width:${a*20}px"></div><div class="bar" style="width:${c*20}px;background:#aa6c36"></div></div><div class="bar-row"><span>O: ${2*b} / ${c}</span><div class="bar" style="width:${b*20}px"></div><div class="bar" style="width:${c*10}px;background:#aa6c36"></div></div><p class="legend">Grönt: vänsterled · Brunt: högerled. Talen visar antal atomer.</p>`;feedback('')});document.getElementById('check').onclick=()=>{let a=n('c0'),b=n('c1'),c=n('c2');if(![a,b,c].every(x=>Number.isInteger(x)&&x>=1&&x<=8)){feedback('Ange heltal mellan 1 och 8.',true);return}feedback(a===2&&b===1&&c===2?'Rätt: 2 H₂ + O₂ → 2 H₂O. Fyra väteatomer och två syreatomer finns på båda sidor.':a===c&&2*b===c?'Reaktionen är balanserad. Kan du förkorta till mindre positiva heltal?':'Atomer skapas inte och försvinner inte. Jämför atomantalet för ett grundämne i taget.',!(a===2&&b===1&&c===2))}}
if(kind==='limiting'){w.innerHTML=`<p class="question">Om du har 6 H₂ och 2 O₂, vilket ämne blir över?</p><div class="equation">2 H₂ + O₂ → 2 H₂O</div><div class="controls">${range('hydrogen','Antal H₂-molekyler',0,12,6)}${range('oxygen','Antal O₂-molekyler',0,6,2)}</div><div class="visual" id="molecules"></div><div class="feedback" id="feedback" aria-live="polite"></div><p class="legend">En förenklad partikelmodell: endast hela reaktionsgrupper om 2 H₂ och 1 O₂ räknas. Vi antar fullständig reaktion. I makroskopiska beräkningar används substansmängder och samma proportion 2:1.</p>`;bind(()=>{let h=n('hydrogen'),o=n('oxygen'),groups=Math.min(Math.floor(h/2),o);document.getElementById('molecules').innerHTML=`<div class="blocks">${[`Bildat: ${2*groups} H₂O`,`Kvar: ${h-2*groups} H₂`,`Kvar: ${o-groups} O₂`].map(x=>`<span class="text-block">${x}</span>`).join('')}</div>`;feedback(h===2*o?'Ämnena finns i exakt proportion. Inget blir över.':h<2*o?'Väte begränsar reaktionen. Varje reaktionsgrupp behöver två H₂-molekyler.':'Syre begränsar reaktionen. Det räcker inte till allt väte.')})}
if(kind==='argument'||kind==='source'){const arg=kind==='argument';const rows=arg?[['Tes','Skolan bör ge plats för en kort läspaus varje dag.','Det här är ståndpunkten skribenten vill få läsaren att acceptera.'],['Argument','En gemensam läspaus ger alla elever tid att läsa.','Detta är ett skäl som stöder tesen.'],['Belägg','I vårt påhittade klassexempel läste 18 av 24 elever under hela pausen.','En observation kan stödja argumentet. Här är siffrorna påhittade för övningen; de bevisar inte en generell effekt.'],['Bemötande','Pausen tar lektionstid, men kan planeras som en del av undervisningen.','Skribenten tar upp en invändning och svarar på den.']]:[['Citat','Läraren skriver: ”Läsning behöver få ta tid.”','Citatet återger källans exakta ord och markeras med citattecken.'],['Referat','Läraren menar att tid behöver avsättas för läsning.','Samma innehåll återges med andra ord. Läsaren får veta vem tanken kommer från.'],['Egen kommentar','Jag tolkar det som att schemat behöver ge utrymme för läsning.','Skribenten markerar sin egen tolkning. Den ska inte presenteras som källans ord.']];w.innerHTML=`<p class="question">${arg?'Vad är skillnaden mellan att ha en åsikt och att stödja den?':'Vilka ord tillhör källan och vilka tillhör skribenten?'}</p><p>Klicka på en textdel för att undersöka dess funktion.</p><div class="blocks">${rows.map((r,i)=>`<button class="text-block" id="row${i}" aria-pressed="false">${r[1]}</button>`).join('')}</div><div id="feedback" class="feedback" aria-live="polite"></div><div class="note"><strong>Pröva själv</strong><p>${arg?'Skriv en egen tes med ett argument. Vilken sorts belägg skulle du behöva för att stärka argumentet?':'Skriv ett eget referat av källmeningen och lägg sedan till en tydligt markerad egen kommentar.'}</p></div><p class="legend">${arg?'Argumentkartan visar en möjlig struktur. Verkliga texter kan byggas på flera sätt.':'Källmeningen är skapad för denna övning. I eget skolarbete behöver du ange en identifierbar källa enligt lärarens instruktioner.'}</p>`;rows.forEach((r,i)=>document.getElementById('row'+i).onclick=()=>{rows.forEach((_,j)=>{let b=document.getElementById('row'+j);b.classList.toggle('selected',i===j);b.setAttribute('aria-pressed',String(i===j))});feedback(r[0]+': '+r[2])})}
if(kind==='tense'){const scenarios=[['I visited London last year.','Simple past','Last year is a finished period. The visit is placed in that past period.',100,'last year'],['I have visited London three times.','Present perfect','This describes experience up to now. No finished past period is specified.',320,'up to now'],['I have lived here for three years.','Present perfect','In this example, I still live here. The situation began in the past and continues now.',320,'past → now']];w.innerHTML=`<p class="question" lang="en">Does the sentence describe a finished past period or connect the past to now?</p><label for="scenario">Choose a sentence</label><div class="controls"><select id="scenario">${scenarios.map((r,i)=>`<option value="${i}">${r[0]}</option>`).join('')}</select></div><div class="visual" lang="en"><div class="equation" id="sentence"></div><svg class="plot" viewBox="0 0 600 100" role="img" aria-label="Timeline from past to now"><path d="M50 45H550" stroke="#68877a" stroke-width="2"/><text x="50" y="80" font-size="15">PAST</text><text x="500" y="80" font-size="15">NOW</text><g id="period"></g></svg><div id="tense-label"></div></div><div id="feedback" lang="en" class="feedback" aria-live="polite"></div><p class="legend">The timeline illustrates these examples, not every use of either tense. Context and varieties of English also matter.</p>`;bind(()=>{let r=scenarios[n('scenario')];document.getElementById('sentence').textContent=r[0];document.getElementById('period').innerHTML=n('scenario')===0?'<circle cx="150" cy="45" r="8" fill="#a96a2e"/>':'<path d="M150 45H520" stroke="#0f766e" stroke-width="8"/><circle cx="520" cy="45" r="8" fill="#0f766e"/>';document.getElementById('tense-label').textContent=r[1]+' · '+r[4];feedback(r[2])})}
if(kind==='connect'){const options=[['Cause','We stayed inside because it was raining.','because','The rain explains why we stayed inside.'],['Contrast','It was raining. However, we went outside.','however','Going outside contrasts with the expectation created by the rain.'],['Result','It was raining, so we stayed inside.','so','Staying inside is presented as a result of the rain.']];w.innerHTML=`<p class="question" lang="en">How does the linking word change the relationship between the ideas?</p><div class="controls"><label for="relation">Choose a relationship<select id="relation">${options.map((r,i)=>`<option value="${i}">${r[0]}</option>`).join('')}</select></label></div><div class="visual" lang="en"><div class="equation" id="linked"></div><p id="relationship"></p></div><div id="feedback" class="feedback" lang="en" aria-live="polite"></div><p lang="en">Try it yourself: write two ideas about homework. Connect them to show a cause, then a contrast.</p>`;bind(()=>{let r=options[n('relation')];document.getElementById('linked').textContent=r[1];document.getElementById('relationship').textContent=r[0]+' → '+r[2];feedback(r[3])})}
}
